// Internationalization (i18n) for the OK Library web UI.
//
// Supports English (en), Korean (ko), Russian (ru), and Greek (el).
// The active language is persisted in localStorage and exposed via the
// `useI18n()` hook. Strings can include `{name}` placeholders that are
// substituted by the second argument to `t()`.
//
// Keep this file as the single source of truth for every user-facing string
// in the web app. New strings MUST be added to all four locales.

import React, { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';

export type Lang = 'en' | 'ko' | 'ru' | 'el';

export const LANGUAGES: Array<{ code: Lang; label: string; flag: string }> = [
  { code: 'en', label: 'English',  flag: '🇬🇧' },
  { code: 'ko', label: '한국어',     flag: '🇰🇷' },
  { code: 'ru', label: 'Русский',  flag: '🇷🇺' },
  { code: 'el', label: 'Ελληνικά', flag: '🇬🇷' }
];

const LANG_STORAGE_KEY = 'ok-library-lang-v1';

// Translation dictionary: every key has an entry per locale. Variables use
// `{name}` syntax. Keep keys grouped by feature for easier maintenance.
