  'settings.vc.vsAuthorities': 'Этот инструмент ПЕРЕЗАПИСЫВАЕТ: сведённые написания исчезают, и следа о них не остаётся. Применяйте его к простой опечатке. Если все написания законны, добавьте авторитетный заголовок выше — он сохранит собственный текст книги и запишет варианты.',
  'borrowers.heading': 'Читатели',
  'borrowers.intro': 'Все, кто берёт книги, что у них на руках и что просрочено. Читатель создаётся автоматически при первой выдаче; здесь ему задают контакт, категорию и примечание.',
  'borrowers.categoryNote': 'Категория определяет, какое правило выдачи применяется — срок, число продлений, сколько книг одновременно. До сих пор задать её было нечем, поэтому все читатели были «standard» и срабатывало только резервное правило. Задайте её здесь, а соответствующее правило напишите в «Правилах выдачи».',
