  'course.welcomeTitle': 'Добро пожаловать',
  'course.welcomeLead': 'Это единственное, что нужно прочитать перед началом работы. Курс короткий, и это тот же текст, что и в справочнике, — значит, ничему из усвоенного здесь дальше не будет противоречия.',
  'course.welcomeBody': 'Вам предстоит работать примерно с 12 700 записями, большей частью греческими и большей частью старше любой из участвующих программ. Курс не о программе. Он о немногих решениях, которые делают каталог полезным, и о том, что представляет собой именно это собрание.',
