  'course.endTitle': 'Это весь курс',
  'course.endLead': 'Восемь глав, и ни одна из них не изменится у вас под руками: это главы справочника, поэтому исправление там — исправление и здесь.',
  'course.endHandbook': 'В справочнике есть ещё двадцать три главы — от штриховых кодов до статистического отчёта. Читать их не обязательно. Открывайте вкладку справочника, когда возникнет вопрос, или нажимайте «?» рядом с любым полем, чтобы попасть в то место, где есть ответ.',
