  'identity.heading': '🏛 Наша библиотека',
  'identity.intro': 'Сведения о библиотеке в том виде, в каком их понимают другие библиотеки. ISIL идентифицирует вас в каждой выгружаемой MARC-записи и в описании OAI-PMH-репозитория: без него записи уходят отсюда без указания учреждения.',
