  'authorities.variantsHelp': 'Ένας ανά γραμμή. Η αναζήτηση βρίσκει την απόδοση από οποιονδήποτε από αυτούς, γι’ αυτό καταγράψτε τις γραφές που πληκτρολογούν στην πράξη.',
