  'settings.vc.vsAuthorities': 'Αυτό το εργαλείο ΞΑΝΑΓΡΑΦΕΙ: οι γραφές που ενοποιείτε χάνονται, χωρίς ίχνος ότι υπήρξαν. Χρησιμοποιήστε το για απλό τυπογραφικό λάθος. Όταν όλες οι γραφές είναι θεμιτές, προσθέστε καθιερωμένη απόδοση παραπάνω — έτσι κρατιέται το κείμενο του βιβλίου και καταγράφονται οι παραλλαγές.',
  'borrowers.heading': 'Αναγνώστες',
  'borrowers.intro': 'Όλοι όσοι δανείζονται, τι έχουν πάρει και τι έχει καθυστερήσει. Ο αναγνώστης δημιουργείται αυτόματα με τον πρώτο δανεισμό· εδώ του δίνετε στοιχεία επικοινωνίας, κατηγορία και σημείωση.',
  'borrowers.categoryNote': 'Η κατηγορία καθορίζει ποιος κανόνας δανεισμού ισχύει — πόσες μέρες, πόσες ανανεώσεις, πόσα βιβλία μαζί. Μέχρι τώρα δεν υπήρχε τρόπος να οριστεί, οπότε κάθε αναγνώστης ήταν «standard» και ίσχυε μόνο ο εφεδρικός κανόνας. Ορίστε την εδώ και γράψτε τον αντίστοιχο κανόνα στους Κανόνες δανεισμού.',
  'borrowers.search': 'Εύρεση αναγνώστη',
