  'borrowers.categoryHelp': 'Γράψτε νέα ή επιλέξτε υπάρχουσα. Πρέπει να συμφωνεί ακριβώς με την κατηγορία του κανόνα δανεισμού, αλλιώς ο αναγνώστης πέφτει στον εφεδρικό κανόνα.',
  'borrowers.notes': 'Σημείωση',
