  'course.welcomeTitle': 'Καλώς ορίσατε',
  'course.welcomeLead': 'Αυτό είναι το ένα πράγμα που πρέπει να διαβάσετε πριν ξεκινήσετε. Είναι σύντομο, και είναι το ίδιο κείμενο με το εγχειρίδιο — οπότε τίποτα από όσα μάθετε εδώ δεν θα αναιρεθεί αργότερα.',
  'course.welcomeBody': 'Αναλαμβάνετε περίπου 12.700 εγγραφές, στην πλειονότητά τους ελληνικές και στην πλειονότητά τους παλαιότερες από κάθε λογισμικό που εμπλέκεται. Το μάθημα δεν αφορά το λογισμικό. Αφορά τις λίγες αποφάσεις που κάνουν έναν κατάλογο να αξίζει, και το πώς είναι αυτή η συγκεκριμένη συλλογή.',
  'course.welcomeTime': '{n} κεφάλαια. Διαβάστε τα με τη σειρά· μπορείτε να επιστρέψετε σε οποιοδήποτε από αυτά αργότερα.',
  'course.begin': 'Έναρξη',
  'course.next': 'Επόμενο',
