  'course.endTitle': 'Αυτό ήταν όλο το μάθημα',
  'course.endLead': 'Οκτώ κεφάλαια, και κανένα δεν θα αλλάξει κάτω από τα χέρια σας: είναι κεφάλαια του εγχειριδίου, οπότε μια διόρθωση εκεί είναι διόρθωση και εδώ.',
  'course.endHandbook': 'Το εγχειρίδιο έχει άλλα είκοσι τρία κεφάλαια — από τους γραμμωτούς κώδικες έως τη στατιστική δήλωση. Δεν χρειάζεται να τα διαβάσετε. Ανοίξτε την καρτέλα του εγχειριδίου όταν προκύψει ερώτημα, ή πατήστε το «?» δίπλα σε οποιοδήποτε πεδίο για να βρεθείτε στο σημείο που το απαντά.',
  'course.endReplay': 'Μπορείτε να διαβάσετε το μάθημα ξανά όποτε θέλετε, από το μενού κάτω από το όνομά σας.',
