  'rooms.intro': 'Οι φυσικοί χώροι όπου βρίσκονται τα ράφια. Ο κωδικός αίθουσας είναι αυτό στο οποίο παραπέμπει κάθε βιβλίο της, οπότε η μετονομασία μετακινεί μαζί και τα βιβλία, ενώ μια αίθουσα δεν διαγράφεται όσο μένουν βιβλία μέσα.',
