  'trash.restoreMergedTitle': 'Επαναφορά ενοποιημένης εγγραφής;',
  'trash.restoreMergedBody': 'Αυτή η εγγραφή διπλώθηκε σε μια άλλη, οπότε η επαναφορά της ξαναδημιουργεί το διπλότυπο που αφαίρεσε η ενοποίηση. Τα αντίτυπά της έμειναν στην εγγραφή που την απορρόφησε, οπότε επιστρέφει με ένα νέο κενό αντίτυπο.',
  'identity.heading': '🏛 Η βιβλιοθήκη μας',
  'identity.intro': 'Ποια είναι αυτή η βιβλιοθήκη, στη μορφή που αναγνωρίζουν οι άλλες βιβλιοθήκες. Το ISIL σας ταυτοποιεί σε κάθε εγγραφή MARC που εξάγετε και στην περιγραφή του αποθετηρίου OAI-PMH — χωρίς αυτό, οι εγγραφές φεύγουν από εδώ χωρίς ταυτότητα ιδρύματος.',
