  'identity.isilHint': 'Διεθνές Πρότυπο Αναγνωριστικό Βιβλιοθηκών. Το αποδίδει η εθνική βιβλιοθήκη· αφήστε το κενό μέχρι να το αποκτήσετε αντί να επινοήσετε κωδικό.',
