  'identity.sharingOff': 'ΑΝΕΝΕΡΓΗ',
  'identity.sharingOffBody': 'Τα SRU και OAI-PMH είναι κλειστά. Κανείς εκτός συστήματος δεν μπορεί να διαβάσει τον κατάλογο.',
  'identity.sharingOnBody': 'Οποιοσδήποτε μπορεί πλέον να αναζητά και να συγκομίζει τις βιβλιογραφικές σας εγγραφές σε αυτές τις διευθύνσεις. Αναγνώστες, δανεισμοί και προσωπικό δεν εκτίθενται ποτέ.',
  'identity.startSharing': 'Δημοσίευση καταλόγου',
