  'identity.shareOnTitle': 'Δημοσίευση του καταλόγου σε όλους;',
  'identity.shareOnBody': 'Αυτό ανοίγει τα SRU και OAI-PMH στο δημόσιο διαδίκτυο, χωρίς λογαριασμό. Μοιράζονται μόνο βιβλιογραφικές εγγραφές — ποτέ αναγνώστες, δανεισμοί ή προσωπικό. Οι συγκομιστές κρατούν δικά τους αντίγραφα, οπότε η απενεργοποίηση δεν αναιρεί όσα έχουν ήδη πάρει.',
